solution:
public static string[] KeepLast(string[] codes)
{
    var seen = new HashSet<string>(StringComparer.Ordinal); var result = new List<string>(); for (int i = codes.Length - 1; i >= 0; i--) if (seen.Add(codes[i])) result.Add(codes[i]); result.Reverse(); return result.ToArray();
}

