public static long[] WindowSums(int[] values, int width)
{
    if (width > values.Length) return []; var result = new List<long>(); long sum = 0; for (int i = 0; i < values.Length; i++) { sum += values[i]; if (i >= width) sum -= values[i-width]; if (i >= width-1) result.Add(sum); } return result.ToArray();
}

