public static int LuhnDigit(string digits)
{
    int sum = 0; bool twice = true; for (int i = digits.Length - 1; i >= 0; i--) { int v = digits[i] - '0'; if (twice) { v *= 2; if (v > 9) v -= 9; } sum += v; twice = !twice; } return (10 - sum % 10) % 10;
}

