public static string[] ParseCsvRow(string row)
{
    var fields = new List<string>(); var field = new System.Text.StringBuilder(); bool quoted = false; for (int i = 0; i < row.Length; i++) { char c = row[i]; if (c == '"') { if (quoted && i + 1 < row.Length && row[i+1] == '"') { field.Append('"'); i++; } else quoted = !quoted; } else if (c == ',' && !quoted) { fields.Add(field.ToString()); field.Clear(); } else field.Append(c); } fields.Add(field.ToString()); return fields.ToArray();
}

