public static int[] DecodeHex(string hex)
{
    if (hex.Length % 2 != 0 || hex.Any(c => !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f' || c >= 'A' && c <= 'F'))) return []; return Convert.FromHexString(hex).Select(b => (int)b).ToArray();
}

