public static long[] ProductsExceptSelf(int[] values)
{
    var result = new long[values.Length]; long product = 1; for (int i = 0; i < values.Length; i++) { result[i] = product; product *= values[i]; } product = 1; for (int i = values.Length-1; i >= 0; i--) { result[i] *= product; product *= values[i]; } return result;
}
